const X=1540,Y=0;
const r=screen("Screens · 02 Entry editor",X,Y,{h:1240});sidebarA(r,SITE_A("Blog posts"));const m=mainCol(r);topbarA(m,["Acme Ltd","Acme Bakery","Blog posts","Spring menu 2027"]);
