const im=fr(two,"Cover",{layout:"vertical",gap:6,width:"fill_container"});const il=fr(im,"l",{gap:6,alignItems:"center"});tx(il,"Cover image",{fontWeight:"500"});tx(il,"*",{fill:"$danger"});ic(il,"lock",{width:12,height:12});tx(il,"Image shared",{fontSize:12,fill:"$muted-fg"});
const ib=fr(im,"box",{width:"fill_container",gap:12,padding:10,cornerRadius:8,stroke:"$border",strokeWidth:1,alignItems:"center"});const th=fr(ib,"thumb",{width:72,height:54,cornerRadius:6,fill:"#F5D0A9",alignItems:"center",justifyContent:"center"});ic(th,"croissant",{width:22,height:22,fill:"#9A3412"});const ic2=fr(ib,"alt",{layout:"vertical",gap:4,width:"fill_container"});tx(ic2,"spring-loaves.jpg · 1600×1200",{fontSize:12,fill:"$muted-fg"});input(ic2,"Alt (Italiano): Tre pani su un tagliere",{value:1});
const rl=fr(two,"Written by",{layout:"vertical",gap:6,width:"fill_container"});const rll=fr(rl,"l",{gap:6,alignItems:"center"});tx(rll,"Written by",{fontWeight:"500"});tx(rll,"*",{fill:"$danger"});ic(rll,"lock",{width:12,height:12});tx(rll,"Shared",{fontSize:12,fill:"$muted-fg"});
const rb2=fr(rl,"box",{width:"fill_container",gap:8,padding:10,cornerRadius:8,stroke:"$border",strokeWidth:1,alignItems:"center",height:76});const ch=fr(rb2,"chip",{padding:[4,8],gap:6,cornerRadius:999,fill:"$muted",alignItems:"center"});avatar(ch,"AK",{size:20,fs:9});tx(ch,"Aoife Kelly",{fontSize:12,fontWeight:"500"});ic(ch,"x",{width:11,height:11});tx(rb2,"Team · add another",{fontSize:12,fill:"$muted-fg"});
