for(const [n,t] of [["1","Rinfresca il lievito madre la sera prima"],["2","Impasta con farina di farro e lascia riposare 12 ore"]]){const it=fr(rp,"Item "+n,{width:"fill_container",padding:[8,10],gap:10,cornerRadius:8,stroke:"$border",strokeWidth:1,alignItems:"center"});ic(it,"grip-vertical",{width:14,height:14});tx(it,n,{fontSize:12,fontWeight:"600",fill:"$muted-fg"});const tw=fr(it,"tw",{width:"fill_container"});tx(tw,t);ic(it,"image",{width:14,height:14});ic(it,"chevron-down",{width:14,height:14});}
const ad=fr(rp,"add",{gap:6,alignItems:"center",padding:[4,2]});ic(ad,"plus",{width:14,height:14,fill:"$primary"});tx(ad,"Add step",{fontWeight:"500",fill:"$primary"});
