tx(s1.b,"Publishes this Entry in every visible language. Authors can only save drafts; an Editor or Owner publishes.",{fontSize:12,fill:"$muted-fg",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});
btn(s1.b,"Edit on site",{icon:"mouse-pointer-click"});
const s2=card(R,"Languages","Turn a language off to hide this Entry there (404, left out of Loops and the sitemap).");
for(const [l,mode,on,k] of [["English","Default",1,"outline"],["Italiano","Review",1,"warn"],["Deutsch","Automatic",1,"info"]]){const rw=fr(s2.b,"L "+l,{width:"fill_container",gap:8,alignItems:"center"});tx(rw,l,{fontWeight:"500"});badge(rw,mode,k);sp(rw);toggle(rw,on);}
