const sd=fr(s3.b,"d",{layout:"vertical",gap:4,width:"fill_container"});const sdl=fr(sd,"l",{width:"fill_container"});tx(sdl,"Description",{fontSize:12,fontWeight:"500"});sp(sdl);tx(sdl,"128 / 160",{fontSize:11,fill:"$muted-fg"});const ta=fr(sd,"ta",{width:"fill_container",padding:10,cornerRadius:8,stroke:"$border",strokeWidth:1,fill:"$bg"});tx(ta,"Tre nuovi pani, una crostata al limone e il primo croissant vegano.",{fontSize:12,textGrowth:"fixed-width",width:"fill_container"});
const og=fr(s3.b,"og",{width:"fill_container",gap:10,alignItems:"center"});const ot=fr(og,"img",{width:64,height:34,cornerRadius:4,fill:"#F5D0A9"});const oc=fr(og,"c",{layout:"vertical",width:"fill_container"});tx(oc,"Open Graph image",{fontSize:12,fontWeight:"500"});tx(oc,"Uses the cover image",{fontSize:11,fill:"$muted-fg"});tx(og,"Change",{fontSize:12,fontWeight:"500",fill:"$primary"});
const s4=card(R,"Details",null);for(const [k,v] of [["Author","Mark O'Brien"],["Created","12 Feb 2027"],["Updated","Today, 10:42"],["Published","3 Mar 2027"]]){const rw=fr(s4.b,"D "+k,{width:"fill_container"});tx(rw,k,{fontSize:12,fill:"$muted-fg"});sp(rw);tx(rw,v,{fontSize:12,fontWeight:"500"});}
